// Generar resumen HTML por cliente
const cliente = $json.cliente;
const totalPedidos = $json.producto.length;
const cantidadTotal = $json.cantidad;
const totalGastado = $json.total;

let detalleProductos = '';
for (let i = 0; i < $json.producto.length; i++) {
  detalleProductos += `<tr>
    <td style="padding:6px 10px;border:1px solid #ddd;">${$json.fecha[i]}</td>
    <td style="padding:6px 10px;border:1px solid #ddd;">${$json.producto[i]}</td>
    <td style="padding:6px 10px;border:1px solid #ddd;text-align:right;">${$json.cantidad[i]}</td>
  </tr>`;
}

const html = `<div style="font-family:Arial,sans-serif;max-width:600px;margin:0 auto;">
  <h2 style="color:#1a73e8;">📊 Resumen de pedidos — ${cliente}</h2>
  <table style="width:100%;border-collapse:collapse;margin:16px 0;">
    <tr><td style="padding:8px;font-weight:bold;">Total pedidos:</td><td style="padding:8px;">${totalPedidos}</td></tr>
    <tr><td style="padding:8px;font-weight:bold;">Unidades compradas:</td><td style="padding:8px;">${cantidadTotal}</td></tr>
    <tr><td style="padding:8px;font-weight:bold;color:#1a73e8;">Total gastado:</td><td style="padding:8px;color:#1a73e8;"><strong>€${totalGastado.toFixed(2)}</strong></td></tr>
  </table>
  <h3 style="color:#333;">Detalle de productos</h3>
  <table style="width:100%;border-collapse:collapse;">
    <thead>
      <tr style="background:#f5f5f5;">
        <th style="padding:8px 10px;border:1px solid #ddd;text-align:left;">Fecha</th>
        <th style="padding:8px 10px;border:1px solid #ddd;text-align:left;">Producto</th>
        <th style="padding:8px 10px;border:1px solid #ddd;text-align:right;">Cant.</th>
      </tr>
    </thead>
    <tbody>
      ${detalleProductos}
    </tbody>
  </table>
</div>`;

return [
  {
    cliente: cliente,
    emailHtml: html,
    asunto: `Resumen de pedidos — ${cliente}`,
    totalGastado: totalGastado
  }
];
